class Solution {
    /** Returns the largest value in nums. */
    public int max(int[] nums) {
        if (nums.length == 0) {
            throw new IllegalArgumentException("nums is empty");
        }
        int largest = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > largest) {
                largest = nums[i];
            }
        }
        return largest;
    }
}

